import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'

export function proxy(request: NextRequest) {
  const { method, nextUrl } = request

  console.log(
    `${new Date().toISOString()} ${method} ${nextUrl.pathname}${nextUrl.search}`
  )

  return NextResponse.next()
}

// No `matcher` is exported, so this runs on every request — including
// `_next/static`, `_next/image`, and files in `public/`. To skip those and log
// only page/route requests, export a matcher such as:
//
// export const config = {
//   matcher: '/((?!_next/static|_next/image|favicon.ico).*)',
// }

